-- New 1a: 13 Hero WODs from crossfit.com/benchmark/<slug>. Generated; not yet run.
do $$
declare n int;
begin
  if exists (select 1 from benchmark_workouts where slug in ('bert', 'big-sexy', 'dg', 'del', 'dork', 'gator', 'hidalgo', 'jag-28', 'jbo', 'kutschbach', 'larry', 'maupin', 'ned')) then raise exception 'slug exists'; end if;
  insert into benchmark_workouts (name, slug, category, subcategory, format, scheme, duration_estimate, difficulty, body_focus, equipment, scoring_type, description, movements, scoring_notes, tips, coaching_tips, scaling_notes, faqs, youtube_url) values
  -- bert
  ('Bert',
   'bert',
   'hero',
   null,
   'For Time',
   'Chipper For Time',
   '45–75 min',
   'intermediate',
   'full-body',
   array['bodyweight','running']::text[],
   'time',
   'Bert honors U.S. Marine Cpl. Albert Gettings, 27, of New Castle, Pennsylvania, a team leader with the 2nd Battalion, 6th Marine Regiment, who died on Jan. 5, 2009, during counter-sniper operations in Fallujah, Iraq. His fellow Marines in Fox Company do a CrossFit workout in his honor each quarter at the Cpl. Albert P. Gettings Award ceremony.

Bert is a long bodyweight chipper. You work down to 200 air squats and back up again, with a 400 m run between every movement. In total that is 100 burpees, 200 push-ups, 300 walking lunges, 200 squats and 2,400 m of running. No single movement is hard, but the volume is huge. The push-ups and lunges come back on tired muscles, so pacing the first half decides how the second half goes.',
   '[{"name": "Burpees", "reps": "50", "tip": "Find a steady rhythm you could keep for 5 minutes and stay with it."}, {"name": "Run", "reps": "400 m", "tip": "Easy pace. Use each run to bring your breathing down."}, {"name": "Push-Ups", "reps": "100", "tip": "Break into small sets of 10 to 15 from the start. Chest touches the floor every rep."}, {"name": "Run", "reps": "400 m", "tip": "Shake out your arms as you run."}, {"name": "Walking Lunges", "reps": "150", "tip": "Back knee touches the floor each step. Count each step as 1 rep."}, {"name": "Run", "reps": "400 m", "tip": "Short steps until your legs loosen up."}, {"name": "Air Squats", "reps": "200", "tip": "Hip crease below the knee. Sets of 25 to 40 with short pauses."}, {"name": "Run", "reps": "400 m", "tip": "Stay relaxed. You are past halfway."}, {"name": "Walking Lunges", "reps": "150", "tip": "Same standard as before. Pause standing tall rather than on one knee."}, {"name": "Run", "reps": "400 m", "tip": "Keep the pace honest even if your legs feel heavy."}, {"name": "Push-Ups", "reps": "100", "tip": "Expect smaller sets now. Short, regular rests beat one long stop."}, {"name": "Run", "reps": "400 m", "tip": "Last run. Breathe through it and get ready for the final burpees."}, {"name": "Burpees", "reps": "50", "tip": "Finish with steady burpees. Chest to the floor, small jump and clap overhead."}]'::jsonb,
   'Record your finish time.',
   '["Pace the first half so the second half is still steady", "Break push-ups early and often", "Use every run to recover, not to race"]'::jsonb,
   '["Start the first 50 burpees at a pace you could repeat at the end of the workout.", "Plan your push-up sets before you start, such as 10 sets of 10, and rest briefly between them.", "On the lunges, keep your torso upright and step far enough that your front knee stays over your foot.", "Break the 200 squats into sets you can finish without stopping mid-set, such as 8 sets of 25.", "Drink water before you start, because this workout can take an hour or more."]'::jsonb,
   'Cut every rep count in half (25 burpees, 50 push-ups, 75 lunges, 100 squats) and keep the 400 m runs, or shorten the runs to 200 m. Do push-ups from the knees or with your hands on a bench or box. Replace walking lunges with step-ups or reverse lunges if space is tight. Row 500 m in place of each run if you cannot run.',
   '[{"question": "What is the Bert workout?", "answer": "For time: 50 burpees, 100 push-ups, 150 walking lunges, 200 air squats, 150 walking lunges, 100 push-ups and 50 burpees, with a 400 m run between each movement."}, {"question": "How many total reps are in Bert?", "answer": "100 burpees, 200 push-ups, 300 walking lunges and 200 air squats, plus six 400 m runs for 2,400 m in all."}, {"question": "Who was Bert?", "answer": "U.S. Marine Cpl. Albert Gettings, 27, a team leader with the 2nd Battalion, 6th Marine Regiment. He died on Jan. 5, 2009, during counter-sniper operations in Fallujah, Iraq."}, {"question": "Do I need any equipment for Bert?", "answer": "No. Bert is all bodyweight plus running, so you only need space to run 400 m."}]'::jsonb,
   'https://www.youtube.com/watch?v=idCQMD8DiE4'),
  -- big-sexy
  ('Big Sexy',
   'big-sexy',
   'hero',
   null,
   'For Time',
   '5 Rounds For Time',
   '20–35 min',
   'advanced',
   'full-body',
   array['barbell','pullUpBar','rings']::text[],
   'time',
   'Big Sexy honors Sgt. Lance "Big Sexy" McLean, 38, of Biloxi, Mississippi, a sergeant and SWAT team member with the Sheriff''s Office in Hood County, Texas. He died on June 29, 2013, from a gunshot wound he received in the line of duty the day before.

The workout is five rounds of six movements in falling reps: 6 deadlifts, 6 burpees, 5 cleans, 5 chest-to-bar pull-ups, 4 thrusters and 4 muscle-ups. The rep counts are low, but the loads are heavy and the gymnastics are advanced. Across the five rounds you lift 30 deadlifts, 25 cleans and 20 thrusters, with 25 chest-to-bar pull-ups and 20 muscle-ups. You need strength, skill and grip all at once.',
   '[{"name": "Deadlifts", "reps": "6", "tip": "Flat back and the bar close to your legs. Short pauses between reps are fine.", "rx_men": "315 lb", "rx_women": "205 lb"}, {"name": "Burpees", "reps": "6", "tip": "Steady pace. Use them to catch your breath before the cleans."}, {"name": "Cleans", "reps": "5", "tip": "Power or squat clean. Singles with a quick reset keep your form clean.", "rx_men": "225 lb", "rx_women": "155 lb"}, {"name": "Chest-to-Bar Pull-Ups", "reps": "5", "tip": "Chest touches the bar on every rep. Do them unbroken or 3 and 2."}, {"name": "Thrusters", "reps": "4", "tip": "Clean the bar, then squat and drive it overhead in one motion.", "rx_men": "155 lb", "rx_women": "105 lb"}, {"name": "Muscle-Ups", "reps": "4", "tip": "Ring or bar. Small sets of 1 or 2 so you don''t miss reps."}]'::jsonb,
   'Record your finish time.',
   '["Treat the heavy lifts as quick singles", "Protect your grip for the muscle-ups", "Set up three bars if you can"]'::jsonb,
   '["Load three bars before you start so you are not changing plates between movements.", "Do the deadlifts and cleans as fast singles, resetting your back position before each rep.", "Use a hook grip on the cleans and shake out your hands before the pull-ups.", "Split the muscle-ups into planned small sets from round one rather than waiting until you fail.", "Keep transitions short, because that is where most of the time goes in this workout."]'::jsonb,
   'Use about 60% of the Rx loads, such as 185 lb / 125 lb deadlifts, 135 lb / 95 lb cleans and 95 lb / 65 lb thrusters. Replace chest-to-bar pull-ups with regular or jumping pull-ups. Replace each muscle-up with 2 pull-ups and 2 dips, or use jumping muscle-ups from a box. Drop to 3 rounds if 5 would take you longer than about 40 minutes.',
   '[{"question": "What is the Big Sexy workout?", "answer": "5 rounds for time of 6 deadlifts (315 lb / 205 lb), 6 burpees, 5 cleans (225 lb / 155 lb), 5 chest-to-bar pull-ups, 4 thrusters (155 lb / 105 lb) and 4 muscle-ups."}, {"question": "How many total reps are in Big Sexy?", "answer": "30 deadlifts, 30 burpees, 25 cleans, 25 chest-to-bar pull-ups, 20 thrusters and 20 muscle-ups, 150 reps in all."}, {"question": "Who was Big Sexy?", "answer": "Sgt. Lance McLean, 38, of Biloxi, Mississippi, a sergeant and SWAT team member with the Sheriff''s Office in Hood County, Texas. He died on June 29, 2013, from a gunshot wound received in the line of duty."}, {"question": "Can the cleans be power cleans?", "answer": "Yes. CrossFit lists cleans, so a power clean or a squat clean both count as long as you stand up fully with the bar on your shoulders."}]'::jsonb,
   'https://www.youtube.com/watch?v=QLD67zvyPHs'),
  -- dg
  ('DG',
   'dg',
   'hero',
   null,
   'AMRAP 10',
   'AMRAP 10',
   '10 min',
   'intermediate',
   'full-body',
   array['pullUpBar','dumbbells']::text[],
   'rounds_reps',
   'DG honors U.S. Air Force Maj. Walter David Gray, 38, of Conyers, Georgia, of the 13th Air Support Operations Squadron at Fort Carson, Colorado. He died on Aug. 8, 2012, from injuries suffered in a suicide-bomb attack in Kunar Province, Afghanistan.

DG is a 10-minute AMRAP of 8 toes-to-bar, 8 dumbbell thrusters and 12 dumbbell walking lunges, using a pair of 35 lb dumbbells for men and 20 lb for women. The loads are moderate, so the workout is about moving without stopping. Toes-to-bar tax your grip and core, the thrusters push your heart rate up, and the lunges burn the legs before the next trip to the bar.',
   '[{"name": "Toes-to-Bar", "reps": "8", "tip": "Both feet touch the bar at the same time. Keep a steady swing and short sets."}, {"name": "Dumbbell Thrusters", "reps": "8", "tip": "Dumbbells on your shoulders, squat below parallel and press straight up.", "rx_men": "35 lb dumbbells", "rx_women": "20 lb dumbbells"}, {"name": "Dumbbell Walking Lunges", "reps": "12", "tip": "Carry the dumbbells at your sides or on your shoulders. Each step counts as 1 rep.", "rx_men": "35 lb dumbbells", "rx_women": "20 lb dumbbells"}]'::jsonb,
   'Score is total rounds + reps.',
   '["Pick up the dumbbells right after you drop off the bar", "Keep toes-to-bar sets short", "Walk back to the bar briskly"]'::jsonb,
   '["Break the toes-to-bar into sets you can repeat every round, such as 4 and 4, before your grip fades.", "Keep your elbows high on the thrusters so the dumbbells stay over your shoulders in the squat.", "Use the hips to drive the dumbbells overhead rather than pressing with your arms alone.", "On the lunges, let the back knee touch the floor gently and stand fully at the top.", "Pace the first two minutes so you can keep the same round speed until the end."]'::jsonb,
   'Use lighter dumbbells, such as 25 lb / 15 lb, or a single dumbbell for the thrusters. Replace toes-to-bar with hanging knee raises or lying leg raises. Do the lunges without dumbbells if the load slows you down too much.',
   '[{"question": "What is the DG workout?", "answer": "As many rounds and reps as possible in 10 minutes of 8 toes-to-bar, 8 dumbbell thrusters and 12 dumbbell walking lunges, with 35 lb / 20 lb dumbbells."}, {"question": "How do you score DG?", "answer": "Count your full rounds, then add the reps from your last partial round. Each round is 28 reps."}, {"question": "Who was DG?", "answer": "U.S. Air Force Maj. Walter David Gray, 38, of the 13th Air Support Operations Squadron at Fort Carson, Colorado. He died on Aug. 8, 2012, after a suicide-bomb attack in Kunar Province, Afghanistan."}, {"question": "Do I use one dumbbell or two?", "answer": "Two. The Rx weight is a pair of 35 lb dumbbells for men and a pair of 20 lb dumbbells for women, used for both the thrusters and the lunges."}]'::jsonb,
   'https://www.youtube.com/watch?v=4ABd86U1xkk'),
  -- del
  ('Del',
   'del',
   'hero',
   null,
   'For Time',
   'Chipper For Time',
   '25–40 min',
   'advanced',
   'full-body',
   array['wallBall','dumbbells','pullUpBar','running']::text[],
   'time',
   'Del honors U.S. Army 1st Lt. Dimitri Del Castillo, 24, of Tampa, Florida, of the 2nd Battalion, 35th Infantry Regiment, 25th Infantry Division, based at Schofield Barracks, Hawaii. He died on June 25, 2011, in Kunar Province, Afghanistan, from wounds suffered when enemy forces attacked his unit with small-arms fire.

Del is a chipper of five movements with a 400 m medicine ball run between each one. You do 25 burpees, 25 weighted pull-ups holding a dumbbell, 25 handstand push-ups, 25 chest-to-bar pull-ups and another 25 burpees. That is 50 pull-ups of two hard kinds, which makes grip and upper-body pulling the main challenge. Carrying the ball on every run keeps your arms and shoulders working even while you move between stations.',
   '[{"name": "Burpees", "reps": "25", "tip": "Steady pace. You have a long way to go."}, {"name": "Run", "reps": "400 m", "tip": "Carry the medicine ball the whole way. Hold it at your chest or on a shoulder.", "rx_men": "20 lb ball", "rx_women": "14 lb ball"}, {"name": "Weighted Pull-Ups", "reps": "25", "tip": "Hold the dumbbell between your feet or use a belt. Chin over the bar each rep.", "rx_men": "20 lb dumbbell", "rx_women": "15 lb dumbbell"}, {"name": "Run", "reps": "400 m", "tip": "Same carry. Switch shoulders if one side tires.", "rx_men": "20 lb ball", "rx_women": "14 lb ball"}, {"name": "Handstand Push-Ups", "reps": "25", "tip": "Head touches the floor or pad, then lock out your arms. Small sets before you fail."}, {"name": "Run", "reps": "400 m", "tip": "Relax your shoulders as you carry the ball.", "rx_men": "20 lb ball", "rx_women": "14 lb ball"}, {"name": "Chest-to-Bar Pull-Ups", "reps": "25", "tip": "Chest touches the bar. Expect small sets now that your grip is tired."}, {"name": "Run", "reps": "400 m", "tip": "Last carry. Push the pace if you can.", "rx_men": "20 lb ball", "rx_women": "14 lb ball"}, {"name": "Burpees", "reps": "25", "tip": "Finish strong with steady burpees."}]'::jsonb,
   'Record your finish time.',
   '["Keep pull-up sets small from the start", "Find a comfortable way to carry the ball", "Save some grip for the chest-to-bar"]'::jsonb,
   '["Practice holding the dumbbell between your feet before the clock starts so it doesn''t slip mid-set.", "Break the weighted pull-ups into sets of 3 to 5 with short rests.", "On handstand push-ups, stop each set one or two reps before you think you would fail.", "Carry the medicine ball high on your chest or on one shoulder, and keep your running stride short.", "Shake out your hands on the third run so your grip has recovered for the chest-to-bar pull-ups."]'::jsonb,
   'Run without the medicine ball, or carry a lighter one. Do the weighted pull-ups at bodyweight, and replace chest-to-bar pull-ups with regular, banded or jumping pull-ups. Replace handstand push-ups with pike push-ups or dumbbell shoulder presses. Cut each movement to 15 reps if 25 would take you more than five minutes.',
   '[{"question": "What is the Del workout?", "answer": "For time: 25 burpees, 25 weighted pull-ups, 25 handstand push-ups, 25 chest-to-bar pull-ups and 25 burpees, with a 400 m run carrying a medicine ball between each movement."}, {"question": "What weights are used in Del?", "answer": "A 20 lb medicine ball and a 20 lb dumbbell for men, and a 14 lb medicine ball and a 15 lb dumbbell for women."}, {"question": "How many total reps are in Del?", "answer": "50 burpees, 25 weighted pull-ups, 25 handstand push-ups and 25 chest-to-bar pull-ups, plus four 400 m medicine ball runs for 1,600 m in all."}, {"question": "Who was Del?", "answer": "U.S. Army 1st Lt. Dimitri Del Castillo, 24, of the 2nd Battalion, 35th Infantry Regiment. He died on June 25, 2011, in Kunar Province, Afghanistan, after an attack on his unit."}]'::jsonb,
   null),
  -- dork
  ('Dork',
   'dork',
   'hero',
   null,
   'For Time',
   '6 Rounds For Time',
   '25–40 min',
   'intermediate',
   'full-body',
   array['jumpRope','kettlebell']::text[],
   'time',
   'Dork honors Boston firefighter Michael Kennedy, 33, who died fighting a nine-alarm fire on March 26, 2014. He served six and a half years with the Boston Fire Department, was a Marine Corps sergeant who served a tour in Iraq, and coached and trained at several CrossFit gyms in the Boston area.

The workout is six rounds of 60 double-unders, 30 kettlebell swings and 15 burpees, for a total of 360 double-unders, 180 swings and 90 burpees. The loads are moderate (53 lb / 35 lb), so this is a test of steady pacing. Double-unders get harder as your calves and shoulders tire, and the swings and burpees keep your heart rate high the whole way.',
   '[{"name": "Double-Unders", "reps": "60", "tip": "Relaxed wrists and small jumps. Break before you trip, not after."}, {"name": "Kettlebell Swings", "reps": "30", "tip": "Drive with your hips and finish with the bell overhead.", "rx_men": "53 lb", "rx_women": "35 lb"}, {"name": "Burpees", "reps": "15", "tip": "Chest to the floor, then a small jump with a clap overhead."}]'::jsonb,
   'Record your finish time.',
   '["Pace round one like it''s round four", "Break the swings into two sets", "Rest standing, not on the floor"]'::jsonb,
   '["Keep the rope turning with your wrists and your elbows close to your sides.", "Split the swings into sets such as 15 and 15 so your grip lasts all six rounds.", "Snap your hips forward on each swing and let the bell float overhead with your arms straight.", "Move straight from the last swing into the burpees without a long pause.", "Note your time for each round and try to keep them within a minute of each other."]'::jsonb,
   'Replace each double-under with 2 single-unders, or cut the double-unders to 30 per round. Use a lighter kettlebell, such as 35 lb / 26 lb, or swing to eye level instead of overhead. Drop to 4 rounds if 6 would take you longer than about 40 minutes.',
   '[{"question": "What is the Dork workout?", "answer": "6 rounds for time of 60 double-unders, 30 kettlebell swings (53 lb / 35 lb) and 15 burpees."}, {"question": "How many total reps are in Dork?", "answer": "360 double-unders, 180 kettlebell swings and 90 burpees, 630 reps in all."}, {"question": "Who was Dork?", "answer": "Boston firefighter Michael Kennedy, 33, who died fighting a nine-alarm fire on March 26, 2014. He was also a Marine Corps sergeant who served in Iraq."}, {"question": "Can I do Dork without double-unders?", "answer": "Yes. Do 2 single-unders for each double-under, or fewer double-unders per round, and note the change with your score."}]'::jsonb,
   'https://www.youtube.com/watch?v=VBlhfP7UPpY'),
  -- gator
  ('Gator',
   'gator',
   'hero',
   null,
   'For Time',
   '8 Rounds For Time',
   '20–35 min',
   'advanced',
   'full-body',
   array['barbell','rings']::text[],
   'time',
   'Gator honors U.S. Army Spc. Christopher "Gator" Gathercole, 21, of Santa Rosa, California, of the 2nd Battalion, 75th Ranger Regiment, based at Fort Lewis, Washington. He was killed by enemy fire on May 26, 2008, in Ghazni, Afghanistan.

Gator is eight rounds of 5 heavy front squats and 26 ring push-ups. Over the eight rounds you do 40 front squats at 185 lb / 125 lb and 208 ring push-ups. The squats are heavy enough to need full focus, and the push-ups add up quickly. Rings wobble, so your chest, shoulders and core all work to keep you steady, and the push-ups are where most people lose time.',
   '[{"name": "Front Squats", "reps": "5", "tip": "Elbows high and chest up. Do all 5 in one set if you can.", "rx_men": "185 lb", "rx_women": "125 lb"}, {"name": "Ring Push-Ups", "reps": "26", "tip": "Rings low to the floor. Chest down to the rings and lock out at the top."}]'::jsonb,
   'Record your finish time.',
   '["Break the ring push-ups from round one", "Keep the squats in one set", "Set the rings close to the floor"]'::jsonb,
   '["Start the bar in a rack so you can begin each set of front squats without cleaning it.", "Brace hard before each squat and drive up through your whole foot.", "Break the 26 ring push-ups into sets such as 10, 8 and 8 before your arms give out.", "Turn your hands slightly out at the top of each push-up to keep the rings steady.", "Keep your body in a straight line from head to heels, with no sagging hips."]'::jsonb,
   'Use about 60–70% of the Rx load, such as 135 lb / 95 lb. Replace ring push-ups with regular push-ups, or raise the rings so the push-ups are easier. Cut the push-ups to 13 per round, or do 5 rounds instead of 8, if the full workout would take you more than about 40 minutes.',
   '[{"question": "What is the Gator workout?", "answer": "8 rounds for time of 5 front squats (185 lb / 125 lb) and 26 ring push-ups."}, {"question": "How many total reps are in Gator?", "answer": "40 front squats and 208 ring push-ups."}, {"question": "Who was Gator?", "answer": "U.S. Army Spc. Christopher Gathercole, 21, of the 2nd Battalion, 75th Ranger Regiment. He was killed by enemy fire on May 26, 2008, in Ghazni, Afghanistan."}, {"question": "Can I do Gator without rings?", "answer": "Yes. Do regular push-ups on the floor. Note the change with your score, since ring push-ups are harder."}]'::jsonb,
   'https://www.youtube.com/watch?v=JRe7IvZ-0yM'),
  -- hidalgo
  ('Hidalgo',
   'hidalgo',
   'hero',
   null,
   'For Time',
   'Chipper For Time',
   '50–75 min',
   'advanced',
   'full-body',
   array['running','barbell','box']::text[],
   'time',
   'Hidalgo honors U.S. Army 1st Lt. Daren M. Hidalgo, 24, of Waukesha, Wisconsin, of the 3rd Squadron, 2nd Stryker Cavalry Regiment, based in Vilseck, Germany. He died on Feb. 20, 2011, in Kandahar Province, Afghanistan, from an improvised explosive device attack, after choosing to stay on patrols despite injuries from an earlier blast.

The workout opens and closes with a 2-mile run, with a 2-minute rest on either side of a barbell and box chipper: 20 squat cleans, 20 box jumps, 20 overhead walking lunges with a plate, 20 box jumps and 20 squat cleans. That is 4 miles of running, 40 squat cleans and 40 box jumps. CrossFit adds that if you have a 20 lb vest or body armor, you should wear it.',
   '[{"name": "Run", "reps": "2 miles", "tip": "Hold a pace you could keep for both runs. The second run comes after a lot of work."}, {"name": "Rest", "reps": "2 min", "isRest": true, "tip": "Catch your breath and set up your station."}, {"name": "Squat Cleans", "reps": "20", "tip": "Catch the bar in a full squat and stand up. Quick singles work well.", "rx_men": "135 lb", "rx_women": "95 lb"}, {"name": "Box Jumps", "reps": "20", "tip": "Stand tall on the box at the top. Step down to save your legs.", "rx_men": "24 in", "rx_women": "20 in"}, {"name": "Overhead Walking Lunges", "reps": "20", "tip": "Plate locked out overhead, arms straight. Each step counts as 1 rep.", "rx_men": "45 lb plate", "rx_women": "25 lb plate"}, {"name": "Box Jumps", "reps": "20", "tip": "Same standard. Keep a steady rhythm.", "rx_men": "24 in", "rx_women": "20 in"}, {"name": "Squat Cleans", "reps": "20", "tip": "Your legs are tired now. Reset your back before every rep.", "rx_men": "135 lb", "rx_women": "95 lb"}, {"name": "Rest", "reps": "2 min", "isRest": true, "tip": "Get water and loosen your legs before the last run."}, {"name": "Run", "reps": "2 miles", "tip": "Settle in. This is the longest part of the workout."}]'::jsonb,
   'Record your finish time, including both 2-minute rests.',
   '["Run the first 2 miles slower than you want to", "Use the rests to set up and drink", "Wear a 20 lb vest only if you have one"]'::jsonb,
   '["Set up your barbell, box and plate before you start the first run so the rest is real rest.", "Do the squat cleans as singles with a short pause, keeping the bar close to your body.", "Step down from the box rather than rebounding, so your calves and Achilles last.", "Keep the plate directly over your head on the lunges, with your ribs down and arms locked.", "Expect the final run to be slower than the first and keep moving even if you need to slow down."]'::jsonb,
   'Leave out the vest. Shorten each run to 1 mile, or row 2,000 m in place of each run. Use a lighter barbell, such as 95 lb / 65 lb, or do power cleans with a front squat. Step up onto the box instead of jumping, and do the lunges with a lighter plate or no weight.',
   '[{"question": "What is the Hidalgo workout?", "answer": "For time: run 2 miles, rest 2 minutes, then 20 squat cleans, 20 box jumps, 20 overhead walking lunges, 20 box jumps and 20 squat cleans, rest 2 minutes, then run 2 miles."}, {"question": "What are the Rx weights for Hidalgo?", "answer": "A 135 lb barbell, 24 in box and 45 lb plate for men, and a 95 lb barbell, 20 in box and 25 lb plate for women. Wear a 20 lb vest or body armor if you have one."}, {"question": "How many total reps are in Hidalgo?", "answer": "40 squat cleans, 40 box jumps and 20 overhead walking lunges, plus 4 miles of running."}, {"question": "Who was Hidalgo?", "answer": "U.S. Army 1st Lt. Daren M. Hidalgo, 24, of the 3rd Squadron, 2nd Stryker Cavalry Regiment. He died on Feb. 20, 2011, in Kandahar Province, Afghanistan, after an improvised explosive device attack."}]'::jsonb,
   'https://www.youtube.com/watch?v=NamLnTfrL2s'),
  -- jag-28
  ('Jag 28',
   'jag-28',
   'hero',
   null,
   'For Time',
   'Chipper For Time',
   '25–40 min',
   'advanced',
   'full-body',
   array['running','kettlebell','pullUpBar']::text[],
   'time',
   'Jag 28 honors U.S. Air Force Senior Airman Mark Forester, 29, of Tuscaloosa, Alabama, of the 21st Special Tactics Squadron at Pope Air Force Base, North Carolina. He died on Sept. 29, 2010, during combat operations in Uruzgan Province, Afghanistan.

Jag 28 is a chipper between two 800 m runs: 28 kettlebell swings, 28 strict pull-ups, 28 kettlebell clean and jerks and 28 more strict pull-ups, with a 70 lb bell for men and 53 lb for women. The 56 strict pull-ups are the hardest part for most people, because there is no kip to help. The heavy kettlebell work in between drains your grip before you get back to the bar.',
   '[{"name": "Run", "reps": "800 m", "tip": "Controlled pace. The real work starts at the kettlebell."}, {"name": "Kettlebell Swings", "reps": "28", "tip": "Drive with your hips and finish with the bell overhead.", "rx_men": "70 lb", "rx_women": "53 lb"}, {"name": "Pull-Ups", "reps": "28", "tip": "Strict: no kip or swing. Chin over the bar from a dead hang each rep."}, {"name": "Kettlebell Clean & Jerks", "reps": "28", "tip": "Clean the bell to the rack position, then dip and drive it overhead. Switch hands as needed.", "rx_men": "70 lb", "rx_women": "53 lb"}, {"name": "Pull-Ups", "reps": "28", "tip": "Strict again. Use small sets with short rests."}, {"name": "Run", "reps": "800 m", "tip": "Last effort. Shake out your arms and push the pace."}]'::jsonb,
   'Record your finish time.',
   '["Strict pull-ups go in small sets from the start", "Protect your grip on the swings", "Keep the runs steady"]'::jsonb,
   '["Break the swings into two or three sets so your grip is ready for the strict pull-ups.", "On strict pull-ups, start each rep from straight arms and pull without swinging your legs.", "For the kettlebell clean and jerk, keep the bell close as you clean it so it lands softly in the rack.", "Use your legs to drive the bell overhead and lock your arm out with the bell over your shoulder.", "Plan your pull-up sets ahead, such as 7 sets of 4, and rest briefly between them."]'::jsonb,
   'Use a lighter kettlebell, such as 53 lb / 35 lb. Replace strict pull-ups with banded pull-ups, jumping pull-ups or ring rows, or cut them to 14 per set. Do kettlebell push presses or a dumbbell clean and jerk if the kettlebell clean and jerk is new to you. Shorten each run to 400 m if needed.',
   '[{"question": "What is the Jag 28 workout?", "answer": "For time: run 800 m, 28 kettlebell swings, 28 strict pull-ups, 28 kettlebell clean and jerks, 28 strict pull-ups, run 800 m, using a 70 lb / 53 lb kettlebell."}, {"question": "How many total reps are in Jag 28?", "answer": "28 kettlebell swings, 56 strict pull-ups and 28 kettlebell clean and jerks, plus 1,600 m of running."}, {"question": "Who was Jag 28?", "answer": "U.S. Air Force Senior Airman Mark Forester, 29, of the 21st Special Tactics Squadron. He died on Sept. 29, 2010, during combat operations in Uruzgan Province, Afghanistan."}, {"question": "Can I kip the pull-ups in Jag 28?", "answer": "No. The Rx version calls for strict pull-ups. If you kip, note it with your score so you can compare later attempts."}]'::jsonb,
   'https://www.youtube.com/watch?v=HYiN_Tj_ep0'),
  -- jbo
  ('JBo',
   'jbo',
   'hero',
   null,
   'AMRAP 28',
   'AMRAP 28',
   '28 min',
   'advanced',
   'full-body',
   array['barbell']::text[],
   'rounds_reps',
   'JBo honors U.S. Army Staff Sgt. Jeremie "JBo" Border, 28, of Mesquite, Texas, of the 1st Battalion, 1st Special Forces Group (Airborne), based at Torii Station, Okinawa, Japan. He died on Sept. 1, 2012, in Batur Village, Afghanistan, from wounds suffered when enemy forces attacked his unit with small-arms fire.

JBo is a 28-minute AMRAP of 9 overhead squats and 12 bench presses, both with the same barbell at 115 lb for men and 75 lb for women. The load is moderate, but 28 minutes is a long time to hold a bar overhead and press it from your chest. Your shoulders and chest tire first. Steady rounds and quick transitions between the squat and the bench matter more than speed.',
   '[{"name": "Overhead Squats", "reps": "9", "tip": "Wide grip, arms locked and the bar over your mid-foot. Squat below parallel.", "rx_men": "115 lb", "rx_women": "75 lb"}, {"name": "Bench Press", "reps": "12", "tip": "Bar touches your chest and your arms lock out at the top. Feet flat on the floor.", "rx_men": "115 lb", "rx_women": "75 lb"}]'::jsonb,
   'Score is total rounds + reps.',
   '["Use one bar for both movements", "Set safety arms on the bench", "Keep every round the same speed"]'::jsonb,
   '["Set the bench next to a rack with safety arms or a spotter, because your arms will tire late in the workout.", "Get the bar overhead with a push press or snatch, then lock your arms before you squat.", "Keep your chest up and push your knees out on the overhead squats.", "Break the bench press into sets such as 6 and 6 before you reach failure.", "Count your rounds with chalk marks or a whiteboard so you don''t lose track over 28 minutes."]'::jsonb,
   'Use a lighter bar, such as 75 lb / 55 lb, or a PVC pipe for the overhead squats if your mobility limits depth. Replace overhead squats with front squats, and bench press with push-ups or dumbbell bench press. Shorten the AMRAP to 20 minutes if 28 is too long for now.',
   '[{"question": "What is the JBo workout?", "answer": "As many rounds and reps as possible in 28 minutes of 9 overhead squats and 12 bench presses, using a 115 lb / 75 lb barbell."}, {"question": "How do you score JBo?", "answer": "Count your full rounds, then add the reps from your last partial round. Each round is 21 reps."}, {"question": "Who was JBo?", "answer": "U.S. Army Staff Sgt. Jeremie Border, 28, of the 1st Battalion, 1st Special Forces Group (Airborne). He died on Sept. 1, 2012, in Batur Village, Afghanistan, after an attack on his unit."}, {"question": "Is it safe to bench press when I''m tired?", "answer": "Use a rack with safety arms set just below chest height, or have a spotter,, and stop each set before you fail."}]'::jsonb,
   'https://www.youtube.com/watch?v=Db7o1C_OHgs'),
  -- kutschbach
  ('Kutschbach',
   'kutschbach',
   'hero',
   null,
   'For Time',
   '7 Rounds For Time',
   '20–35 min',
   'advanced',
   'full-body',
   array['barbell']::text[],
   'time',
   'Kutschbach honors U.S. Army Staff Sgt. Patrick Kutschbach, 25, of McKees Rocks, Pennsylvania, of the 1st Battalion, 10th Special Forces Group in Germany. He died on Nov. 10, 2007, in Bagram, Afghanistan, from injuries sustained when his vehicle was hit by a rocket-propelled grenade and small-arms fire in the Tagab Valley.

Kutschbach is seven rounds of 11 back squats and 10 jerks. Across the workout you do 77 back squats at 185 lb / 125 lb and 70 jerks at 135 lb / 95 lb. There is no running or gymnastics, only two barbell movements, so leg strength and the ability to keep lifting with tired legs decide your time. The squats tire the legs that you need to drive every jerk.',
   '[{"name": "Back Squats", "reps": "11", "tip": "Bar on your upper back, squat below parallel and stand tall. Use a rack.", "rx_men": "185 lb", "rx_women": "125 lb"}, {"name": "Jerks", "reps": "10", "tip": "Dip and drive the bar overhead. Push, power or split jerk all count.", "rx_men": "135 lb", "rx_women": "95 lb"}]'::jsonb,
   'Record your finish time.',
   '["Set up two bars in racks", "Break the squats before they slow down", "Use your legs to drive the jerks"]'::jsonb,
   '["Load two bars, one in a squat rack and one for the jerks, so you never change plates.", "Brace before you unrack the squat bar and keep your chest up as you stand.", "Break the 11 squats into sets such as 6 and 5 if you can''t do them unbroken.", "On the jerks, keep the dip short and straight down, then push yourself under the bar.", "Lock out every jerk overhead with your feet back under you before you bring the bar down."]'::jsonb,
   'Use about 60–70% of the Rx loads, such as 135 lb / 95 lb back squats and 95 lb / 65 lb jerks. Replace jerks with push presses if the jerk is new to you. Do 5 rounds instead of 7 if the full workout would take you longer than about 35 minutes.',
   '[{"question": "What is the Kutschbach workout?", "answer": "7 rounds for time of 11 back squats (185 lb / 125 lb) and 10 jerks (135 lb / 95 lb)."}, {"question": "How many total reps are in Kutschbach?", "answer": "77 back squats and 70 jerks, 147 reps in all."}, {"question": "Who was Kutschbach?", "answer": "U.S. Army Staff Sgt. Patrick Kutschbach, 25, of the 1st Battalion, 10th Special Forces Group. He died on Nov. 10, 2007, in Bagram, Afghanistan, from injuries sustained in an attack in the Tagab Valley."}, {"question": "What kind of jerk should I use?", "answer": "CrossFit lists jerks, so a push jerk, power jerk or split jerk all count. Choose the style you can repeat safely when tired."}]'::jsonb,
   'https://www.youtube.com/watch?v=MigoDXC9EZY'),
  -- larry
  ('Larry',
   'larry',
   'hero',
   null,
   'For Time',
   '21-18-15-12-9-6-3 For Time',
   '12–20 min',
   'intermediate',
   'full-body',
   array['barbell']::text[],
   'time',
   'Larry honors U.S. Marine Corps Cpl. Larry D. Harris, Jr., 25, a fire team leader with Weapons Company, 3rd Battalion, 1st Marines, who was killed in a firefight on July 1, 2010, in Helmand Province, Afghanistan. He was awarded the Silver Star after his death for carrying a wounded Marine to safety under heavy enemy fire.

Larry is a descending ladder of front squats and bar-facing burpees: 21, 18, 15, 12, 9, 6 and 3 reps of each, for a total of 84 front squats and 84 burpees. The load is moderate (115 lb / 75 lb), so you can move quickly. The big early sets are where you can lose the most time, and the burpees right after each squat set keep your heart rate high.',
   '[{"name": "Front Squats", "reps": "21-18-15-12-9-6-3", "tip": "Clean the bar up from the floor, then squat with elbows high.", "rx_men": "115 lb", "rx_women": "75 lb"}, {"name": "Bar-Facing Burpees", "reps": "21-18-15-12-9-6-3", "tip": "Chest to the floor facing the bar, then a two-foot jump over it."}]'::jsonb,
   'Record your finish time.',
   '["Break the set of 21 before it breaks you", "Stay close to the bar on burpees", "Speed up as the reps drop"]'::jsonb,
   '["Break the first two sets of front squats into smaller sets, such as 11 and 10, before your legs fail.", "Keep your elbows high so the bar stays on your shoulders as you stand up.", "Land each burpee with your chest close to the bar so you can jump straight over it.", "Jump and land on two feet over the bar, and step back in without a long pause.", "From the set of 9, try to move without stopping, since the end is close."]'::jsonb,
   'Use a lighter bar, such as 75 lb / 55 lb, or a pair of dumbbells for the front squats. Do step-over burpees or regular burpees if jumping the bar is too much. Use a shorter ladder, such as 15-12-9-6-3, if the full version would take you more than about 25 minutes.',
   '[{"question": "What is the Larry workout?", "answer": "21-18-15-12-9-6-3 reps for time of front squats (115 lb / 75 lb) and bar-facing burpees."}, {"question": "How many total reps are in Larry?", "answer": "84 front squats and 84 bar-facing burpees, 168 reps in all."}, {"question": "Who was Larry?", "answer": "U.S. Marine Corps Cpl. Larry D. Harris, Jr., 25, of the 3rd Battalion, 1st Marines. He was killed in a firefight on July 1, 2010, in Helmand Province, Afghanistan, and was awarded the Silver Star after his death."}, {"question": "What is a bar-facing burpee?", "answer": "A burpee done facing the barbell, with your chest to the floor and then a two-foot jump over the bar. You land facing it again for the next rep."}]'::jsonb,
   'https://www.youtube.com/watch?v=l_SzB5INgEg'),
  -- maupin
  ('Maupin',
   'maupin',
   'hero',
   null,
   'For Time',
   '4 Rounds For Time',
   '35–55 min',
   'intermediate',
   'full-body',
   array['running','bodyweight']::text[],
   'time',
   'Maupin honors U.S. Army Staff Sgt. Keith "Matt" Maupin, 24, of Batavia, Ohio, who served with the 724th Transportation Company in Bartonville, Illinois. He went missing on April 9, 2004, when insurgents attacked his convoy south of Baghdad, and his remains were found on March 20, 2008.

Maupin is four rounds of an 800 m run, 49 push-ups, 49 sit-ups and 49 squats. That is 3,200 m of running and 196 reps of each bodyweight movement. Because no equipment is needed, almost anyone can do it, but the push-up volume is high. Most people slow down most on the push-ups in rounds three and four, so plan your sets from the start.',
   '[{"name": "Run", "reps": "800 m", "tip": "Steady pace you can repeat four times."}, {"name": "Push-Ups", "reps": "49", "tip": "Chest to the floor and lock out at the top. Break into sets of 10 to 15."}, {"name": "Sit-Ups", "reps": "49", "tip": "Shoulders touch the floor, then hands touch your feet or the floor beyond them."}, {"name": "Air Squats", "reps": "49", "tip": "Hip crease below the knee and stand all the way up."}]'::jsonb,
   'Record your finish time.',
   '["Break push-ups early", "Keep the runs steady", "Move straight from one station to the next"]'::jsonb,
   '["Start the first run at a pace you could hold for all four rounds.", "Plan your push-ups as small sets, such as 15, 12, 12 and 10, with short rests.", "On sit-ups, use an abmat or folded towel under your lower back if you have one.", "Keep a steady rhythm on the squats and avoid resting at the bottom.", "Use the run to recover your breathing, not to win back time."]'::jsonb,
   'Cut the reps to 25 per movement and the run to 400 m. Do push-ups from the knees or with your hands on a bench or box. Row 1,000 m or bike in place of each run if you cannot run.',
   '[{"question": "What is the Maupin workout?", "answer": "4 rounds for time of an 800 m run, 49 push-ups, 49 sit-ups and 49 air squats."}, {"question": "How many total reps are in Maupin?", "answer": "196 push-ups, 196 sit-ups and 196 air squats, plus 3,200 m of running."}, {"question": "Who was Maupin?", "answer": "U.S. Army Staff Sgt. Keith \"Matt\" Maupin, 24, of the 724th Transportation Company. He went missing on April 9, 2004, after an attack on his convoy south of Baghdad, and his remains were found on March 20, 2008."}, {"question": "Do I need equipment for Maupin?", "answer": "No. You only need space to run 800 m and a spot on the floor for push-ups, sit-ups and squats."}]'::jsonb,
   'https://www.youtube.com/watch?v=Hltwi807SAQ'),
  -- ned
  ('Ned',
   'ned',
   'hero',
   null,
   'For Time',
   '7 Rounds For Time',
   '45–70 min',
   'advanced',
   'full-body',
   array['barbell','rower']::text[],
   'time',
   'Ned honors Special Agent Nathan "Ned" Schuldheiss, 27, of Newport, Rhode Island, a civilian with the Air Force Office of Special Investigations, Detachment 204, at Offutt Air Force Base, Nebraska. He died on Nov. 1, 2007, near Balad Air Base, Iraq, when an improvised explosive device struck his vehicle.

Ned is seven rounds of 11 back squats at your own bodyweight and a 1,000 m row. That adds up to 77 heavy back squats and 7,000 m of rowing. The squats are heavy for most athletes and the rows are long, so this is a test of strength and steady pacing. Your legs never get a full break, because the row also uses them hard.',
   '[{"name": "Back Squats", "reps": "11", "tip": "Load the bar to your bodyweight. Squat below parallel from a rack.", "rx_men": "Bodyweight", "rx_women": "Bodyweight"}, {"name": "Row", "reps": "1,000 m", "tip": "Long strokes at a steady pace. Legs, then hips, then arms."}]'::jsonb,
   'Record your finish time.',
   '["Load the bar to your bodyweight", "Row at a pace you can hold for seven rounds", "Break the squats early"]'::jsonb,
   '["Weigh yourself before the workout and load the bar to the nearest plate.", "Set the bar in a rack with safety arms, and step back only one or two steps to squat.", "Break the 11 squats into sets such as 4, 4 and 3 if your legs are not ready for unbroken sets.", "On the rower, push with your legs first and keep the stroke rate calm, around 24 to 28 strokes per minute.", "Expect the later rounds to be slower and keep the row split steady."]'::jsonb,
   'Use a lighter bar, such as 50–75% of your bodyweight, or do goblet squats with a dumbbell or kettlebell. Cut the row to 500 m, or do 5 rounds instead of 7. A bike or run of similar time can replace the row if you don''t have a rower.',
   '[{"question": "What is the Ned workout?", "answer": "7 rounds for time of 11 back squats at your bodyweight and a 1,000 m row."}, {"question": "How many total reps are in Ned?", "answer": "77 back squats at bodyweight and 7,000 m of rowing."}, {"question": "Who was Ned?", "answer": "Special Agent Nathan Schuldheiss, 27, a civilian with the Air Force Office of Special Investigations. He died on Nov. 1, 2007, near Balad Air Base, Iraq, when an improvised explosive device struck his vehicle."}, {"question": "What weight do I use for the squats in Ned?", "answer": "Your own bodyweight. Load the bar as close to your bodyweight as your plates allow."}]'::jsonb,
   'https://www.youtube.com/watch?v=iSqAXk7r6Vw');
  get diagnostics n = row_count; if n <> 13 then raise exception 'expected % inserts', 13; end if;
