select slug, scheme from benchmark_workouts where slug in ('bert', 'big-sexy', 'dg', 'del', 'dork', 'gator', 'hidalgo', 'jag-28', 'jbo', 'kutschbach', 'larry', 'maupin', 'ned') order by slug;
